  "title": "Beginner Quant Research",
  "version": "v1",
  "generated_at": "2026-05-11T00:21:09.417907+08:00",
  "knowledge_sections": [
    {
      "title": "Core concepts",
      "summary": "Quantitative trading means turning an idea into explicit rules, testable data assumptions and repeatable review steps.",
      "beginner_actions": [
        "Write down the rule in plain language before coding it.",
        "Keep the first strategy narrow enough that you can explain every input."
      ],
      "avoid_for_now": [
        "Do not start from dozens of indicators and ad-hoc parameter tuning.",
        "Do not treat a narrative or a chatbot summary as a trade signal by itself."
      ],
      "examples": [
        "A simple example is: only observe symbols with stable liquidity, positive trend and a clear invalidation level."
      ],
      "warnings": [
        "If you cannot describe why a rule should stop working, you do not understand the strategy boundary yet."
      ],
      "terms": [
        {
          "term": "factor",
          "definition": "A measurable input that may explain return differences.",
          "example": "Momentum and quality are common factors.",
          "common_misunderstanding": "A factor is not a guaranteed edge forever."
        },
        {
          "term": "max drawdown",
          "definition": "The largest peak-to-trough loss during a period.",
          "example": "A strategy up 20% but down 15% along the way still has a painful drawdown.",
          "common_misunderstanding": "High return with unmanageable drawdown is not beginner friendly."
        },
        {
          "term": "turnover",
          "definition": "How frequently the portfolio changes.",
          "example": "Higher turnover usually means more cost and more execution sensitivity.",
          "common_misunderstanding": "High turnover is not automatically better."
        }
      ]
    },
    {
      "title": "Research workflow",
      "summary": "A safer workflow is hypothesis -> data check -> backtest -> simulation -> review, not idea -> live trade.",
      "beginner_actions": [
        "Record sample period, fee/slippage assumptions and what counts as a failure.",
        "Split validation into at least development and out-of-sample review."
      ],
      "avoid_for_now": [
        "Do not trust a single backtest run without checking another market regime."
      ],
      "examples": [
        "A rule that looks great only in one strong trend year should stay in research or simulation."
      ],
      "warnings": [
        "Missing data-quality checks can create false confidence through look-ahead bias or survivor bias."
      ],
      "terms": [
        {
          "term": "out-of-sample",
          "definition": "A period not used to design the rule.",
          "example": "It is the closest thing to a fair exam for the strategy.",
          "common_misunderstanding": "Good in-sample performance does not imply good out-of-sample performance."
        },
        {
          "term": "slippage",
          "definition": "The difference between expected execution price and actual execution price.",
          "example": "Fast intraday strategies are much more sensitive to slippage.",
          "common_misunderstanding": "Ignoring slippage can make a fragile strategy look good."
        }
      ]
    },
    {
      "title": "Risk control",
      "summary": "For beginners, position sizing, diversification and pause rules are often more important than finding one more indicator.",
      "beginner_actions": [
        "Define single-position and portfolio exposure limits before the first paper trade.",
        "Limit watchlist size so you can review every name properly."
      ],
      "avoid_for_now": [
        "Do not increase risk because one recent trade worked well.",
        "Do not concentrate several highly related names into one theme bet without noticing it."
      ],
      "examples": [
        "Owning several AI-chip names can look diversified by ticker count but still be one theme exposure."
      ],
      "warnings": [
        "If drawdown, execution anomaly or data anomaly is triggered, the next step should usually be review, not more trading."
      ],
      "terms": [
        {
          "term": "position sizing",
          "definition": "How much capital one idea is allowed to use.",
          "example": "A good idea can still hurt if the size is too large.",
          "common_misunderstanding": "Entry direction and position size are separate decisions."
        },
        {
          "term": "capacity",
          "definition": "How much money a strategy can realistically handle.",
          "example": "A minute-level strategy on illiquid names has lower capacity than a daily large-cap strategy.",
          "common_misunderstanding": "Capacity is not only about account size; it is also about liquidity."
        }
      ]
    },
    {
      "title": "Performance evaluation",
      "summary": "Headline return is incomplete; you need return, drawdown, risk-adjusted return, turnover, sample size and stability together.",
      "beginner_actions": [
        "Review both return and the path taken to achieve it.",
        "Keep a small scorecard for every strategy version and compare changes carefully."
      ],
      "avoid_for_now": [
        "Do not upgrade a strategy just because one parameter set has the highest profit."
      ],
      "examples": [
        "A slightly lower return with much smaller drawdown and lower turnover may be the better beginner choice."
      ],
      "warnings": [
        "If a strategy only wins after aggressive tuning, it may be overfit rather than robust."
      ],
      "terms": [
        {
          "term": "Sharpe ratio",
          "definition": "A rough measure of return per unit of volatility.",
          "example": "Higher is usually better, but only when sample quality is acceptable.",
          "common_misunderstanding": "Sharpe alone does not capture tail risk or execution friction."
        },
        {
          "term": "stability",
          "definition": "Whether results stay reasonable across periods, assets or parameter ranges.",
          "example": "A robust rule should not collapse after a small parameter change.",
          "common_misunderstanding": "The best single backtest number is not the same as stability."
        }
      ]
    }
  ],
  "research_findings": [
    {
      "topic": "workflow",
      "conclusion": "Beginners should prioritise evidence-backed, low-frequency and reviewable workflows over minute-level automation.",
      "evidence_level": "high",
      "verification_status": "verified",
      "invalidation_conditions": [
        "If the user already has proven minute-level execution infrastructure and monitoring, this may be relaxed."
      ]
    },
    {
      "topic": "validation",
      "conclusion": "Out-of-sample checks, transaction costs and data-quality notes are mandatory before moving beyond research or backtest summaries.",
      "evidence_level": "high",
      "verification_status": "verified",
      "invalidation_conditions": [
        "Missing cost or data-quality assumptions should block stage upgrades."
      ]
    },
    {
      "topic": "llm_usage",
      "conclusion": "LLM tools are useful for evidence summarisation and candidate explanation, but they should remain research helpers rather than execution authorities.",
      "evidence_level": "mid",
      "verification_status": "verified",
      "invalidation_conditions": [
        "If an LLM output bypasses rule-based screening or risk control, treat the workflow as unsafe."
      ]
    },
    {
      "topic": "risk_budget",
      "conclusion": "A written risk budget and stop conditions should exist before the first simulation session, not after the first drawdown.",
      "evidence_level": "mid",
      "verification_status": "verified",
      "invalidation_conditions": [
        "If the user cannot explain the stop rule, the plan is not ready for upgrade."
      ]
    }
  ],
  "practice_order": [
